from datetime import date, timedelta


class Loyalty:
    def __init__(self) -> None:
        # Per-customer list of (available_from_day, points)
        self._purchases = {}
        # Per-customer list of (day, points) redemptions
        self._redemptions = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        if amount is None:
            raise ValueError("amount must be a number")
        if amount <= 0:
            raise ValueError("purchase amount must be positive")

        # 1 point per full 10.00 spent
        points = int(amount // 10)
        available_from = day + timedelta(days=14)

        self._purchases.setdefault(customer, []).append((available_from, points))
        return points

    def _earned_by(self, customer: str, day: date) -> int:
        total = 0
        for available_from, pts in self._purchases.get(customer, ()):
            if available_from <= day:
                total += pts
        return total

    def _redeemed_by(self, customer: str, day: date) -> int:
        total = 0
        for red_day, pts in self._redemptions.get(customer, ()):
            if red_day <= day:
                total += pts
        return total

    def balance(self, customer: str, day: date) -> int:
        return self._earned_by(customer, day) - self._redeemed_by(customer, day)

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points is None or not isinstance(points, int):
            raise ValueError("points must be an integer")
        if points <= 0:
            raise ValueError("points must be positive")
        if points % 100 != 0:
            raise ValueError("points must be redeemed in multiples of 100")

        if points > self.balance(customer, day):
            raise ValueError("insufficient available points")

        self._redemptions.setdefault(customer, []).append((day, points))
```

